<?php

declare(strict_types=1);

namespace App\Storage;

/**
 * Resolves an identifier the data engine reports for a tmp cleaning
 * result (see docs/data-cleaning.md) to an absolute path on this side of
 * the shared storage volume — with the same containment/symlink checks
 * LocalFilesystemDatasetStorage applies to permanent storage identifiers.
 * The identifier is generated by the (trusted, internal) data engine, not
 * by any end user, but resolution is still verified defensively.
 */
final class TempStorageResolver
{
    private readonly string $rootDir;

    public function __construct(string $tmpDir)
    {
        $this->rootDir = rtrim($tmpDir, '/\\');
    }

    /**
     * @throws StorageException if the identifier doesn't resolve to a file
     *                           inside the tmp root, or that file is missing
     */
    public function resolve(string $identifier): string
    {
        if ($identifier === '' || str_contains($identifier, "\0") || str_contains($identifier, '..')) {
            throw new StorageException('Invalid temporary file identifier.');
        }

        $candidate = $this->rootDir.'/'.$identifier;

        if (is_link($candidate)) {
            throw new StorageException('Temporary file not found.');
        }

        $real = realpath($candidate);
        $realRoot = realpath($this->rootDir);

        if ($real === false || $realRoot === false || !str_starts_with($real, $realRoot)) {
            throw new StorageException('Temporary file not found.');
        }

        if (!is_file($real)) {
            throw new StorageException('Temporary file not found.');
        }

        return $real;
    }
}
